Here is an example of ASP.NET C# code that uses Stripe's API to create a subscription with a trial period and a specific trial amount:
```
using Stripe;
using Stripe.Checkout;
using System;
using System.Web.Mvc;

namespace StripeExample
{
    public class StripeController : Controller
    {
        // Replace with your Stripe secret key
        private string _stripeSecretKey = "YOUR_STRIPE_SECRET_KEY";

        [HttpPost]
        public ActionResult CreateSubscription()
        {
            var stripeConfig = new StripeConfiguration(_stripeSecretKey);
            var service = new SubscriptionService(stripeConfig);

            // Set up the customer payment method
            var customer = service.CreateCustomer(new CustomerCreateOptions
            {
                Description = "Example customer",
                Email = "customer@example.com"
            });

            // Set up the subscription plan
            var plan = service.CreatePlan(new PlanCreateOptions
            {
                Amount = 1000, // 10.00 per month
                Currency = "usd",
                Interval = "month",
                IntervalCount = 1,
                Name = "Monthly Subscription",
                TrialPeriodDays = 14, // 14-day trial
                TrialAmount = 500, // 5.00 trial amount
                Description = "Our monthly subscription plan"
            });

            // Create the subscription
            var subscription = service.CreateSubscription(customer.Id, plan.Id, new SubscriptionCreateOptions
            {
                Quantity = 1,
                EndsAt = DateTime.Now.AddMonths(3) // subscription ends in 3 months
            });

            return RedirectToAction("SubscriptionCreated", new { subscriptionId = subscription.Id });
        }

        public ActionResult SubscriptionCreated(string subscriptionId)
        {
            return View("SubscriptionCreated", new { subscriptionId });
        }
    }
}
```
