    jvmtiEnv* jvmti_env;
    vm->GetEnv((void**)&jvmti_env, JVMTI_VERSION_1);
    return jvmti_env->AddTransformer(&transformer);
}

JNIEXPORT void JNICALL transformer(jvmtiEnv *jvmti_env,
                                  JNIEnv *jni_env,
                                  jclass class_loader,
                                  char* class_name,
                                  jvmtiInfoClassInfo *class_info,
                                  jint status) {
    // Transform the class
    if (strcmp(class_name, "com/example/MyClass") == 0) {
        // Get the method info
        jvmtiInfoMethod(method_info, NULL);
        jvmtiEnv *jvmti_env;
        method_info->GetCode(&method_code);
        jvmtiEnv *jvmti_env;
        method_code->GetBytecodes(&bytecodes);
        // Modify the bytecodes
        int i;
        for (i = 0; i < bytecode_size; i++) {
            bytecodes[i] = (bytecode_t)0x90; // NOP
        }
        method_code->SetBytecodes(bytecodes, bytecode_size);
    }
}

