Here's an example of a program that demonstrates the use of the Boost Interprocess library for process synchronization using shared memory, semaphores, and message queues.

**Shared Memory Example**

We'll create two programs: `shared_memorySender.cpp` and `shared_memoryReceiver.cpp`. The first program will initialize a shared memory segment and write some data to it. The second program will connect to the shared memory segment and read the data.

```cpp
// shared_memorySender.cpp
#include <boost/interprocess/shared_memory_object.hpp>
#include <boost/interprocess/allocators/private_allocator.hpp>
#include <boost/interprocess/mapped_region.hpp>
#include <sstream>
#include <string>

int main() {
    // Initialize shared memory segment
    boost::interprocess::shared_memory_object shm boost::interprocess::create_only, "shared_memory");
    shm.set_size(1024);

    // Map the shared memory segment to a region
    boost::interprocess::mapped_region region(shm, boost::interprocess::read_write);

    // Write some data to the shared memory segment
    std::ostringstream oss;
    oss << "Hello from shared memory!";
    char* data = const_cast<char*>(region.get_address());
    std::copy(oss.str().c_str(), oss.str().c_str() + oss.str().size(), data);

    // Dispose of the shared memory segment
    shm.remove();

    return 0;
}
```

```cpp
// shared_memoryReceiver.cpp
#include <boost/interprocess/shared_memory_object.hpp>
#include <boost/interprocess/allocators/private_allocator.hpp>
#include <boost/interprocess/mapped_region.hpp>
#include <string>

int main() {
    // Initialize shared memory segment
    boost::interprocess::shared_memory_object shm(boost::interprocess::open_only, "shared_memory");
    shm.attach();

    // Map the shared memory segment to a region
    boost::interprocess::mapped_region region(shm, boost::interprocess::read_only);

    // Read data from the shared memory segment
    char* data = const_cast<char*>(region.get_address());
    std::string dataStr(data, std::strlen(data));

    // Print the data
    std::cout << dataStr << std::endl;

    // Dispose of the shared memory segment
    shm.detach();

    return 0;
}
```

**Semaphore Example**

We'll create two programs: `semaphoreSender.cpp` and `semaphoreReceiver.cpp`. The first program will initialize a semaphore and wait for it to be released before writing some data. The second program will acquire the semaphore and then release it.

```cpp
// semaphoreSender.cpp
#include <boost/interprocess/semaphore.hpp>
#include <boost/interprocess/exceptions.hpp>

int main() {
    // Initialize a semaphore
    boost::interprocess::semaphore sem(1, 0); // 1 slot, 0 value

    // Wait for the semaphore to be released
    sem.wait(60); // wait for 1 minute

    // Write some data
    std::cout << "Hello from semaphore!" << std::endl;

    // Release the semaphore
    sem.post(1); // increment the value by 1

    return 0;
}
