El árbol binario se representa a través de la clase `Node` que tiene un valor (de tipo `int`) y dos hijos (izquierda y derecha). La clase `BinarySearchTree` es la que implementa el árbol binario y contiene la función `search()` para buscar un valor en el árbol.

```cpp
#include <iostream>
#include <queue>

using namespace std;

// Representación de un nodo del árbol binario
class Node {
public:
    int value;
    Node* left;
    Node* right;

    Node(int value) {
        this->value = value;
        this->left = nullptr;
        this->right = nullptr;
    }
};

// Representación del árbol binario
class BinarySearchTree {
public:
    Node* root;

    BinarySearchTree() {
        this->root = nullptr;
    }

    // Inserta un valor en el árbol
    void insert(int value) {
        Node* newNode = new Node(value);
        if (root == nullptr) {
            root = newNode;
        } else {
            Node* current = root;
            Node* parent = nullptr;
            while (true) {
                parent = current;
                if (value < current->value) {
                    current = current->left;
                    if (current == nullptr) {
                        parent->left = newNode;
                        return;
                    }
                } else {
                    current = current->right;
                    if (current == nullptr) {
                        parent->right = newNode;
                        return;
                    }
                }
            }
        }
    }

    // Busca un valor en el árbol
    Node* search(int value) {
        Node* current = root;
        while (current != nullptr) {
            if (value == current->value) {
                return current;
            } else if (value < current->value) {
                current = current->left;
            } else {
                current = current->right;
            }
        }
        return nullptr;
    }
};

int main() {
    BinarySearchTree bst;
    bst.insert(5);
    bst.insert(3);
    bst.insert(7);
    bst.insert(2);
    bst.insert(4);
    bst.insert(6);
    bst.insert(8);

    Node* result = bst.search(6);
    if (result != nullptr) {
        cout << "Valor encontrado: " << result->value << endl;
    } else {
        cout << "Valor no encontrado" << endl;
    }

    return 0;
}
```

