```js
const { VercelRequest, VercelResponse } = require('@vercel/node');

exports.handler = function (request, response) {
  response.status(200).json({
    body: request.body,
    query: request.query,
    cookies: request.cookies,
  });
};
```
**Option 2: Use ESM (ES6) exports with a wrapper**

Alternatively, you can create a minimal wrapper around your ES6 code to make it compatible with Vercel's execution environment. Here's the modified code:
```js
import { VercelRequest, VercelResponse } from '@vercel/node';

export const handler = function (request, response) {
  response.status(200).json({
